"""Summarise the complete constrained-control campaign and its costs."""
from pathlib import Path
import json,csv,statistics,hashlib,os
import numpy as np
ROOT=Path(os.environ.get('DFBA_CONTROL_OUTPUT',Path(__file__).resolve().parents[1]/'reference'));R=ROOT/'results'
load=lambda p:json.loads(p.read_text())
P=load(ROOT/'protocol.json');methods=load(ROOT/'protocol_amendment_02.json')['changes']['methods'];names={'direct_single_start':'Direct single start','direct_multistart':'Direct multistart','database_warmstart':'Database + correction','quadratic_ridge':'Quadratic + correction','mlp':'Neural + correction'}
rows=[load(p) for p in sorted((R/'policies').glob('*.json'))];complete=load(R/'campaign_complete.json') if (R/'campaign_complete.json').exists() else None
assert complete and len(rows)==complete['expected_runs']==180,'Do not summarize a partial campaign as complete'
lock=load(R/'selection_lock.json');costs=complete['costs'];traincost=costs['data']['training']['seconds'];valcost=costs['data']['validation']['seconds'];testcost=costs['data']['test']['seconds']
summary=[];caseids=sorted({r['case_id'] for r in rows});case_rows=[]
for method in methods:
 rr=[r for r in rows if r['method']==method];feasible=[r for r in rr if r['tight_verification']['feasible']];offline=0 if method.startswith('direct_') else traincost+(0 if method=='database_warmstart' else valcost+costs['fit'][method]);online=sum(r['online_total_seconds'] for r in rr);calls=sum(r['total_mechanistic_attempts'] for r in rr)
 summary.append({'method':method,'runs':len(rr),'verified_feasible':len(feasible),'median_actual_calls':statistics.median(r['total_mechanistic_attempts'] for r in rr),'total_actual_calls':calls,'median_first_ordinary_feasible_call':statistics.median(r['first_feasible_ordinary_evaluation'] for r in rr if r['first_feasible_ordinary_evaluation'] is not None),'median_online_seconds':statistics.median(r['online_total_seconds'] for r in rr),'mean_online_seconds':online/len(rr),'sum_online_seconds':online,'offline_seconds_required_by_method':offline,'offline_seconds_conservative_full_development_bundle':0 if method.startswith('direct_') else traincost+valcost+(costs['fit'][method] if method in costs['fit'] else 0),'total_seconds_for_recorded_36_decisions':offline+online,'final_tight_seconds':sum(r['tight_verification_seconds'] for r in rr),'failed_mechanistic_attempts':sum(r['failed_mechanistic_evaluation_count'] for r in rr),'proposal_seconds':sum((r['proposal'] or {}).get('seconds',0) for r in rr),'margin_selection_fallbacks':sum(r['selection_mode']!='optimization_margin_feasible' for r in rr)})
for case in caseids:
 cr=[r for r in rows if r['case_id']==case];feasible=[r for r in cr if r['tight_verification']['feasible']];best=max([r['tight_verification']['biomass_amount_gDW'] for r in feasible],default=float('nan'))
 for method in methods:
  rr=[r for r in cr if r['method']==method];v=[r['tight_verification']['biomass_amount_gDW'] for r in rr if r['tight_verification']['feasible']];case_rows.append({'case_id':case,'condition_id':rr[0]['condition_id'],'target_ratio':rr[0]['target_ratio'],'method':method,'feasible_repeats':len(v),'median_feasible_biomass_gDW':float(np.median(v)) if v else None,'max_feasible_biomass_gDW':max(v) if v else None,'best_pooled_recorded_biomass_gDW':best,'median_gap_to_best_pooled_percent':100*(best-float(np.median(v)))/best if v else None})
base=next(r for r in summary if r['method']=='direct_single_start')
for r in summary:
 r['total_prespecified_seconds_for_recorded_36_decisions']=r['offline_seconds_conservative_full_development_bundle']+r['sum_online_seconds']
 r['total_required_seconds_for_recorded_36_decisions']=r['offline_seconds_required_by_method']+r['sum_online_seconds']
 diff=base['mean_online_seconds']-r['mean_online_seconds'];r['estimated_reuse_break_even_vs_single_start']=r['offline_seconds_required_by_method']/diff if diff>0 and r['offline_seconds_required_by_method']>0 else None;r['break_even_scope']='Mean recorded online cost extrapolation only; excludes common pre-existing table and separately reported research validation.'
sens=load(R/'initial_condition_sensitivity.json');senssummary=[]
for method in methods:
 sr=[s for s in sens['cases'] if s['method']==method];er=[s['ratio_relative_error_percent'] for s in sr if s.get('status')=='completed'];senssummary.append({'method':method,'perturbations':len(sr),'nominal_tolerance_passes':sum(s['feasible'] for s in sr),'max_relative_ratio_error_percent':max(er) if er else None,'scope':'48 prescribed perturbations:12cases x4corners, seed3101 only; correlated deterministic sensitivity, not a robustness probability'})
report={'status':'Completed computational study, full design coverage','conditions':P['conditions']['test'],'test_condition_clusters':4,'target_cases':12,'algorithm_seeds_per_case':3,'policy_runs':len(rows),'method_summary':summary,'case_summary':case_rows,'prediction_metrics':load(R/'prediction_metrics.json'),'selection':lock['selection'],'common_offline_costs':{'training_seconds':traincost,'validation_seconds':valcost,'test_audit_label_seconds':testcost,'fit':costs['fit'],'table_construction':'pre-existing shared table, excluded equally'},'cost_interpretation':'The prespecified amendment02 allocation charges training+validation generation to all reuse methods. Also report an explicitly labeled necessary-cost alternative: database requires training labels only, while learned families need validation and all fitting/selection. Both measured totals are retained; no policy/data changes. Research test/audit/sensitivity/direct costs are separate from deployment costs.','campaign':complete,'sensitivity':senssummary,'caveats':['One model pair;4 unseen initial-condition clusters, not independent biological replicates','No global optimum reference; pooled best recorded results are descriptive','No feedback; fixed-policy initial-condition perturbations are sensitivity tests','Direct KKT uses same intracellular solver/matrices, separate amount balances','No experimental validation or assumed neural advantage']}
(R/'summary.json').write_text(json.dumps(report,indent=2)+'\n')
for name,data in [('method_summary.csv',summary),('case_summary.csv',case_rows),('sensitivity_summary.csv',senssummary)]:
 with (R/name).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)
print(json.dumps({'method_summary':summary,'prediction_metrics':report['prediction_metrics'],'sensitivity':senssummary},indent=2))
